#include <stdio.h>

int main(void) {
    int n, x;
    int stack[100000];
    int size = 0;

    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        scanf("%d", &x);
        if (x == 0) {
            if (size > 0) {
                size--;
            }
        } else {
            stack[size++] = x;
        }
    }

    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += stack[i];
    }

    printf("%d\n", sum);
    return 0;
}
